      "summary": "首页 > 院内要闻 近日，中国科学院院长、党组书记侯建国就学习习近平总书记在加强基础研究座谈会上的重要讲话精神，以更大力度、更实举措加强基础研究在中国科学院古脊椎动物与古人类研究所调研。中国科学院副院长、党组成员周琪，副秘书长文亚陪同调研。 侯建国一行实地调研了研究所近期重要工作进展和重大成果，了解分子古生物学、拟石古",
